response:
To create a simple YAML parser in Go without using third-party libraries, you can follow these steps:

1. Define a `YAMLNode` type as a map to store the parsed data.
2. Implement a `ParseYAML` function that takes a string input and returns a `YAMLNode`.
3. Use the `parseYAMLLines` function to process each line of the input.
4. Implement the `getIndent` function to determine the indentation level of a line.
5. Use the `parseSimpleValue` function to convert simple values to appropriate Go types.

Here's a basic implementation:

```go
type YAMLNode map[string]interface{}

func ParseYAML(input string) YAMLNode {
	lines := strings.Split(input, "\n")
	return parseYAMLLines(lines)
}

func parseYAMLLines(lines []string) YAMLNode {
	node := YAMLNode{}
	currentNode := &node
	for _, line := range lines {
		indent := getIndent(line)
		key, value := parseYAMLLine(line)
		if indent == 0 {
			currentNode = &YAMLNode{key: value}
			node = *currentNode
		} else {
			for i := 0; i < indent; i++ {
				currentNode = &(*currentNode)[key]
			}
			*currentNode = YAMLNode{key: value}
		}
	}
	return node
}

func getIndent(s string) int {
	return len(s) - len(strings.TrimLeft(s, " "))
}

func parseYAMLLine(line string) (string, interface{}) {
	parts := strings.SplitN(line, ":", 2)
	key := strings.TrimSpace(parts[0])
	if len(parts) == 2 {
		value := strings.TrimSpace(parts[1])
		return key, parseSimpleValue(value)
	}
	return key, nil
}

func parseSimpleValue(value string) interface{} {
	if value == "true" {
		return true
	} else if value == "false" {
		return false
	} else if i, err := strconv.Atoi(value); err == nil {
		return i
	} else if f, err := strconv.ParseFloat(value, 64); err == nil {
		return f
	}
	return value
}
```

This implementation provides a basic structure for parsing YAML. It handles simple key-value pairs and supports basic data types like integers, floats, and booleans. You can expand it to handle more complex YAML structures as needed.
